      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "No processamento descrito, após a separação óleo-água, a água produzida segue para tratamento, ajuste aos limites ambientais e posterior descarte no mar em instalações marítimas ou reinjeção em instalações terrestres.",
          "trechos": [
            "E45028360f7f635fa:0:695"
          ],
          "condicoes": [
            "Após separação das fases no sistema de tratamento",
            "Com atendimento aos limites ambientais mencionados genericamente na fonte"
          ],
          "limites": [
            "A fonte não informa parâmetros de controle nem limites numéricos",
            "O foco principal do recorte é resíduos e materiais perigosos; este achado é apenas contextual"
          ]
        },
        {
          "proposicao": "A ocorrência de TENORM na indústria de E&P foi documentada historicamente em óleo e gás, com casos relatados no Brasil em incrustações de plataformas da Bacia de Campos, motivando estudos e ações de gerenciamento de resíduos com TENORM.",
          "trechos": [
            "E45028360f7f635fa:695:1389",
            "E45028360f7f635fa:1389:2087"
          ],
          "condicoes": [
            "No contexto de ocorrência de radionuclídeos associados à produção de hidrocarbonetos"
          ],
          "limites": [
            "A fonte não apresenta critérios de classificação, segregação ou armazenamento desses resíduos",
            "Os radionuclídeos identificados estão parcialmente apagados"
          ]
        },
        {
          "proposicao": "Materiais trazidos à superfície na produção de hidrocarbonetos podem coexistir com contaminantes radiológicos, o que conecta a operação de produção ao gerenciamento ocupacional e ambiental de resíduos contaminados.",
          "trechos": [
            "E45028360f7f635fa:1389:2087",
            "E45028360f7f635fa:2087:2214"
          ],
          "condicoes": [
            "Durante a produção de hidrocarbonetos"
          ],
          "limites": [
            "A fonte apenas introduz o mecanismo geral e não descreve medidas de controle operacional",
            "Sem detalhamento de compatibilidade com outros resíduos ou de transporte"
          ]
        }
      ]
    },
